-- ======================================================================
-- TWO MISSPELLED SCHOOL NAMES
-- ======================================================================
-- Generated by scripts/build_statement_requirements_import_sql.py.
-- NOT APPLIED. Run it once, in the SQL editor, and read the result.
--
-- WHAT IT TOUCHES: public.schools.name, two rows, named by id.
-- WHAT IT DOES NOT TOUCH: the statement catalog, which stores no school
-- name and joins for it. Nothing in Statement Studio changes shape.
--
-- IDEMPOTENT AND NARROW. Each UPDATE matches on the id AND the current
-- wrong name, so running it twice is a no-op and running it against a
-- row somebody has already corrected by hand changes nothing.
--
--   504d74ce-7ab1-44af-a7c2-60b241fbb407
--     'Ceder Crest'                          -> 'Cedar Crest College'
--     misspelled, and shortened: the research set's own name for this programme is 'Cedar Crest College'
--   fef27c4e-a9a8-4dd4-82d9-92c8c218ff8f
--     'Saint Marys University of Minnesota'  -> "Saint Mary's University of Minnesota"
--     the possessive apostrophe is part of the name
--
-- ONE STATEMENT, because the SQL editor shows only the last result.
-- ======================================================================

with corrections(school_id, wrong_name, right_name) as (values
  ('504d74ce-7ab1-44af-a7c2-60b241fbb407'::uuid, 'Ceder Crest', 'Cedar Crest College'),
  ('fef27c4e-a9a8-4dd4-82d9-92c8c218ff8f'::uuid, 'Saint Marys University of Minnesota', 'Saint Mary''s University of Minnesota')
),
updated as (
  update public.schools as s
     set name = c.right_name
    from corrections as c
   where s.id = c.school_id
     and s.name = c.wrong_name
  returning s.id, c.wrong_name, s.name as new_name
)
select c.school_id,
       c.wrong_name,
       c.right_name,
       case
         when u.id is not null then 'CORRECTED'
         when s.id is null then 'MISSING: no school with this id'
         when s.name = c.right_name then 'ALREADY CORRECT'
         else 'UNCHANGED: the name is now ' || s.name
       end as verdict
  from corrections as c
  left join updated as u on u.id = c.school_id
  left join public.schools as s on s.id = c.school_id
 order by c.school_id;
